# Generated by AgentFoundry Agent Foundry — DO NOT EDIT BY HAND.
# Records every agent run to .codenow/runs/{slug}/ as JSONL so the AgentFoundry IDE
# can replay it. Wraps any async iterable of messages from the Claude Agent SDK
# (or any other source) and passes messages through unchanged.
#
# Each event is hash-chained (SHA-256, canonical JSON) so the JSONL is
# tamper-evident. The chain head is also written to .codenow/runs/{slug}/heads.jsonl
# after run.end — that's the offline anchor target (push to S3 Object Lock /
# GCS Bucket Lock from your CI to lock the audit trail in place).
#
# Failure policy: this file MUST NEVER throw into your agent. Every IO call
# is wrapped in try/except — if recording breaks, the agent keeps running.

import hashlib
import json
import os
import time
import uuid
from pathlib import Path
from typing import Any, AsyncIterator, Optional

RUNS_DIR = ".codenow/runs"
CAP_PER_SLUG = 100
CAP_TOTAL = 500
MAX_FIELD_BYTES = 100 * 1024
HASH_DOMAIN = "codenow-v1"  # domain separator — must match recorder-hash.js


def _find_project_root() -> Path:
    # Prefer .codenow/agent-studio (only present at the real project root,
    # never inside a per-agent slug subfolder), falling back to .codenow.
    cur = Path.cwd()
    for _ in range(10):
        try:
            if (cur / ".codenow" / "agent-studio").exists():
                return cur
        except Exception:
            pass
        if cur.parent == cur:
            break
        cur = cur.parent
    cur = Path.cwd()
    for _ in range(10):
        try:
            if (cur / ".codenow").exists():
                return cur
        except Exception:
            pass
        if cur.parent == cur:
            break
        cur = cur.parent
    return Path.cwd()


def _safe_serializable(obj: Any) -> Any:
    try:
        if hasattr(obj, "model_dump"):
            return _safe_serializable(obj.model_dump())
        if hasattr(obj, "__dict__"):
            return {k: _safe_serializable(v) for k, v in vars(obj).items() if not k.startswith("_")}
        if isinstance(obj, (list, tuple)):
            return [_safe_serializable(x) for x in obj]
        if isinstance(obj, dict):
            return {k: _safe_serializable(v) for k, v in obj.items()}
        if isinstance(obj, (str, int, float, bool)) or obj is None:
            if isinstance(obj, str) and len(obj) > MAX_FIELD_BYTES:
                return obj[:MAX_FIELD_BYTES] + f"…[truncated {len(obj) - MAX_FIELD_BYTES} chars]"
            return obj
        return repr(obj)
    except Exception:
        return repr(obj)


def _strip_chain_fields(obj: Any) -> Any:
    """Remove _h/_p recursively so the hash never self-references."""
    if isinstance(obj, dict):
        return {k: _strip_chain_fields(v) for k, v in obj.items() if k not in ("_h", "_p")}
    if isinstance(obj, list):
        return [_strip_chain_fields(x) for x in obj]
    return obj


def _canonical_json(value: Any) -> str:
    """Canonical JSON: keys sorted, no whitespace, _h/_p stripped at every level.
    Must match the JS recorder-hash module byte-for-byte for cross-language verify."""
    cleaned = _strip_chain_fields(_safe_serializable(value))
    return json.dumps(cleaned, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def _hash_event(event: Any, prev_hash: Optional[str]) -> str:
    h = hashlib.sha256()
    h.update(HASH_DOMAIN.encode("utf-8"))
    h.update(b"|")
    h.update((prev_hash or "").encode("utf-8"))
    h.update(b"|")
    h.update(_canonical_json(event).encode("utf-8"))
    return h.hexdigest()


def _safe_write_event(fh, event: Any, prev_hash: Optional[str]) -> Optional[str]:
    """Threads the hash chain. Returns the new head hash. On write failure,
    returns prev_hash so the chain stays consistent on disk."""
    new_hash = _hash_event(event, prev_hash)
    if fh is None:
        return new_hash
    try:
        stamped = dict(_safe_serializable(event))
        stamped["_p"] = prev_hash
        stamped["_h"] = new_hash
        fh.write(json.dumps(stamped, ensure_ascii=False) + "\n")
        fh.flush()
        return new_hash
    except Exception:
        return prev_hash


def _safe_append_head(slug_dir: Path, run_id: str, head_hash: Optional[str]) -> None:
    """Append the chain head to a side file after run.end so external anchoring
    (S3 Object Lock / GCS Bucket Lock) can pick it up."""
    if not head_hash:
        return
    try:
        heads_path = slug_dir / "heads.jsonl"
        with open(heads_path, "a", encoding="utf-8") as f:
            f.write(json.dumps({"runId": run_id, "headHash": head_hash, "ts": int(time.time() * 1000)}) + "\n")
    except Exception:
        pass


def _safe_write_line(fh, obj: Any) -> None:
    if fh is None:
        return
    try:
        fh.write(json.dumps(_safe_serializable(obj), ensure_ascii=False) + "\n")
        fh.flush()
    except Exception:
        pass


def _prune(runs_root: Path) -> None:
    try:
        if not runs_root.exists():
            return
        all_files = []
        for slug_dir in runs_root.iterdir():
            if not slug_dir.is_dir():
                continue
            files = sorted(
                [f for f in slug_dir.iterdir() if f.suffix == ".jsonl"],
                key=lambda f: f.stat().st_mtime,
                reverse=True,
            )
            for f in files[CAP_PER_SLUG:]:
                try: f.unlink()
                except Exception: pass
            all_files.extend(files[:CAP_PER_SLUG])
        all_files.sort(key=lambda f: f.stat().st_mtime, reverse=True)
        for f in all_files[CAP_TOTAL:]:
            try: f.unlink()
            except Exception: pass
    except Exception:
        pass


async def record(
    stream: AsyncIterator[Any],
    *,
    slug: str,
    input: str,
    kit: Optional[str] = None,
    agent_version: Optional[str] = None,
    model: Optional[str] = None,
) -> AsyncIterator[Any]:
    start_ts = int(time.time() * 1000)
    run_id = uuid.uuid4().hex[:16]
    project_root = _find_project_root()
    runs_root = project_root / RUNS_DIR
    slug_dir = runs_root / slug
    try: slug_dir.mkdir(parents=True, exist_ok=True)
    except Exception: pass
    _prune(runs_root)

    file_path = slug_dir / f"{start_ts}-{run_id}.jsonl"
    fh = None
    try: fh = open(file_path, "a", encoding="utf-8")
    except Exception: fh = None

    # Threaded hash — head moves forward with every event written. None = genesis.
    head: Optional[str] = None

    head = _safe_write_event(fh, {
        "kind": "run.start",
        "runId": run_id,
        "slug": slug,
        "ts": start_ts,
        "input": input,
        "kit": kit,
        "model": model,
        "agentVersion": agent_version,
        "source": "local",
    }, head)

    last_result_message = None
    errored = False
    try:
        async for message in stream:
            head = _safe_write_event(fh, {"kind": "message", "ts": int(time.time() * 1000), "message": message}, head)
            try:
                if hasattr(message, "result") or (isinstance(message, dict) and "result" in message):
                    last_result_message = message
            except Exception:
                pass
            yield message
    except BaseException as err:
        errored = True
        head = _safe_write_event(fh, {
            "kind": "run.error",
            "ts": int(time.time() * 1000),
            "durationMs": int(time.time() * 1000) - start_ts,
            "error": {"message": str(err), "type": type(err).__name__},
        }, head)
        if fh is not None:
            try: fh.close()
            except Exception: pass
        _safe_append_head(slug_dir, run_id, head)
        raise

    if not errored:
        head = _safe_write_event(fh, {
            "kind": "run.end",
            "ts": int(time.time() * 1000),
            "durationMs": int(time.time() * 1000) - start_ts,
            "status": "success",
            "resultMessage": last_result_message,
        }, head)
    if fh is not None:
        try: fh.close()
        except Exception: pass
    _safe_append_head(slug_dir, run_id, head)
